 * an embedded Go template in single quotes). A quoting mistake there passes
 * typecheck, passes build and passes lint, then fails on a customer's live server
 * mid-cutover as an EMPTY inventory — which the engine reads as "this machine has
 * nothing on it". So the shell is parsed by a real shell here.
 * ------------------------------------------------------------------ */

test("the source inventory script is valid POSIX shell, as root and via sudo", () => {
  for (const priv of ["", "sudo -n "]) {
    const text = srcInventoryScript(priv);
    const file = join(tmpdir(), `nxeon-inv-${priv ? "sudo" : "root"}-${process.pid}.sh`);
    writeFileSync(file, text);
    try {
      // `sh -n` parses without executing: nothing here touches the machine.
      execFileSync("sh", ["-n", file], { stdio: "pipe" });
      execFileSync("dash", ["-n", file], { stdio: "pipe" });
    } finally {
      rmSync(file, { force: true });
    }
  }
});

test("the inventory script emits the authoritative container count before inspecting", () => {
  // CCOUNT is what stands between a docker-inspect template abort and a report
  // that says "0 containers" — so it must be emitted, and emitted from a source
  // that does NOT depend on the template it is there to check.
  const text = srcInventoryScript("");
  assert.match(text, /docker ps -aq[^\n]*wc -l/, "the count comes from docker ps, not from the inspect template");
  assert.match(text, /printf 'CCOUNT/);
  assert.ok(
    text.indexOf("CCOUNT") < text.indexOf('docker inspect "$cid"'),
    "the count is read BEFORE the per-container inspect, so a template abort cannot suppress it"
  );
  // The template must not be able to abort on a container with no devices.
  assert.match(text, /devices \{\{if \.HostConfig\.Devices\}\}/);
});

