 * script is written to the target over SFTP and run with `sh` rather than
 * assembled in a shell — so there is no injection surface.
 */
function staleSweepScript(dirs: string[], needles: string[], work: string): string {
  const pruneExpr = SWEEP_EXCLUDE_DIRS.map((d) => `-name ${d}`).join(" -o ");
  const nameExcl = SWEEP_EXCLUDE_GLOBS.map((g) => `! -name '${g}'`).join(" ");
  const needleArgs = needles.map((n) => `-e ${n}`).join(" ");
