    "export LC_ALL=C",
    'if command -v timeout >/dev/null 2>&1; then TO="timeout 120"; else TO=""; fi',
    `LIST=${work}/stale-files.lst`,
    // `grep -I` below skips binaries; the size cap and prune/exclude lists keep
    // this bounded even on a large tree.
    `find ${dirs.join(" ")} \\( -type d \\( ${pruneExpr} \\) -prune \\) -o ` +
      `\\( -type f -size -${SWEEP_MAX_FILE_SIZE} ${nameExcl} -print0 \\) 2>/dev/null > "$LIST"`,
    'if [ -s "$LIST" ]; then',
    // -o prints ONLY the matched needle, so a matched line containing a password
    // in a connection string never leaves the box. The needle pass is omitted
    // entirely when there is nothing to look for; the certificate pass still runs.
    ...(needles.length
      ? [`  $TO xargs -0 -r grep -I -H -n -o -F ${needleArgs} -- < "$LIST" 2>/dev/null | head -n ${SWEEP_MAX_HITS} | awk '{print "HIT\\t" $0}'`]
