export type StaleSweepResult = {
  hits: StaleHit[];
  /** certificate name → first file that referenced it. */
  certRefs: Map<string, string>;
  /** The script printed its completion marker. Without this NOTHING was proven. */
  ok: boolean;
};

/**
 * Parse the stale-reference sweep's tab-delimited output.
 *
 * TWO defects from the 2026-07-26 rehearsal live here, and the second is the
 * reason this is a named, tested function instead of an inline loop:
 *
 *  1. It read `clean(out.stdout).split("\n")`, and `clean` deletes tabs. The very
 *     next statement was `raw.indexOf("\t") < 0 → continue`, so EVERY line was
 *     skipped, 100% of the time, on every run this code has ever had.
 *  2. The caller then reported "nothing in the copied files still points at the
 *     old server" — status `running`, a clean bill of health — produced by
 *     parsing zero lines. This is the detection for field note 11 ("a frontend
 *     calling the old server's API is a silent failure"), and it was answering
 *     the question without ever having looked.
 *
 * `SWEEP_OK` was already being printed by the script and had never been read.
 * It is now the difference between "we looked and it is clean" and "we could not
 * look" — the caller must not claim the former without `ok`.
 */
export function parseStaleSweep(stdout: string, maxHits = SWEEP_MAX_HITS): StaleSweepResult {
  const hits: StaleHit[] = [];
  const certRefs = new Map<string, string>();
  const seenHit = new Set<string>();
  let ok = false;
  // cleanRows, NOT clean().split(): `clean` strips the tab this parse is keyed on.
  for (const raw of cleanRows(stdout, 60000)) {
    const tab = raw.indexOf("\t");
    if (tab < 0) continue;
    const kind = raw.slice(0, tab);
    const rest = raw.slice(tab + 1);
    if (kind === "SWEEP_OK") {
      ok = true;
      continue;
    }
    const hit = parseSweepHit(rest);
    if (!hit) continue;
    if (kind === "HIT") {
      const key = `${hit.file}|${hit.value}`;
      if (seenHit.has(key) || hits.length >= maxHits) continue;
      seenHit.add(key);
      hits.push(hit);
    } else if (kind === "CERTREF") {
      const name = normalizeDomain(hit.value.slice(hit.value.lastIndexOf("/") + 1));
      if (name && !certRefs.has(name)) certRefs.set(name, hit.file);
    }
  }
  return { hits, certRefs, ok };
}

