// ===========================================================================
// MySQL APPLICATION ACCOUNTS
// ===========================================================================
/**
 * Parse `mysql -N -B -e "SELECT user, host FROM mysql.user"` into a set of
 * `user@host` keys. `-B` is TAB-separated, one account per LINE.
 *
 * Incident (2026-07-26 rehearsal): this was `clean(stdout).split("\n").map(l =>
 * l.split(/\s+/).slice(0,2).join("@"))`, and `clean` deletes BOTH separators, so
 * the whole table collapsed into one garbage key like
 * `readonly%shopapplocalhost`. Nothing ever matched, so `landed` was always
 * empty and the run pushed — at status `failed`, the loudest the summary has —
 * "none of the 3 application database account(s) could be recreated". Ground
 * truth on that run: all three existed, with their original password hashes and
 * grants, and the apps could log in. Field note 15's fix worked; only its
 * verification lied. Since `failed` steps now drive the outcome, this single
 * glued string also downgraded every migration that carried a DB account.
 *
 * A host column is optional in output shapes that omit it; a lone user name is
 * still recorded so the caller can match on `user@%` if it must.
 */
export function parseMysqlUserList(stdout: string): Set<string> {
  const out = new Set<string>();
  for (const row of cleanRows(stdout, 8000)) {
    // Tab is the -B separator; fall back to any whitespace run for `-t`/aligned
    // output. User names may contain spaces in MySQL, but never a tab.
    const cols = (row.includes("\t") ? row.split("\t") : row.split(/\s+/)).map((c) => c.trim()).filter(Boolean);
    if (!cols.length) continue;
    const [user, host] = cols;
    if (!user) continue;
    out.add(host ? `${user}@${host}` : user);
  }
  return out;
}

