export function isServing(code: string): boolean {
  return /^[1-4]\d\d$/.test(code);
}

/**
 * Every TCP port bound on this machine, from `ss -lnt | awk '{print $4}'` —
 * one `ADDRESS:PORT` per LINE (`0.0.0.0:80`, `[::]:443`, `127.0.0.1:3105`).
 *
 * Incident (2026-07-26 rehearsal): this read `clean(stdout).split("\n")` and
 * matched `/:(\d{1,5})$/` per "line". `clean` deletes the newlines, so all of
 * `ss`'s output arrived as ONE string and the `$`-anchored regex matched only
 * the very last port on the box. The set that is supposed to hold every bound
 * port held exactly one, essentially at random.
 *
 * That is not cosmetic. `appPorts` is `containerPorts.filter(p =>
 * listening.has(p))`, and `appPorts` is the fallback upstream used to synthesise
 * a vhost when the source's config yields none — so a container app that WAS
 * bound and serving got no vhost generated, and the customer's domain answered
 * with the stock distribution page. It also decides `proxyPort` for every vhost
 * built from a source `proxy_pass`.
 */
export function parseListeningPorts(stdout: string): Set<number> {
  const ports = new Set<number>();
  for (const l of cleanRows(stdout, 12000)) {
    const m = /:(\d{1,5})$/.exec(l);
    if (!m) continue; // the `Local Address:Port` header row, and IPv6 without a port
    const p = Number(m[1]);
    if (Number.isInteger(p) && p >= 1 && p <= 65535) ports.add(p);
  }
  return ports;
}

/**
 * The variables a compose file REQUIRES from its environment: `${VAR}` with no
 * default. `${VAR:-fallback}` and `${VAR-fallback}` supply their own value and
 * are deliberately excluded.
 *
 * Incident (2026-07-26 rehearsal): built from `clean(stdout).split("\n")` over
 * `grep -o '\$\{...\}'` output, which is one token per line. Glued, the whole
 * list became `${DB_PASSWORD}${REDIS_URL}${API_KEY}` and the `^`-anchored regex
 * returned only the first name. Field note 12 exists to REFUSE to start a stack
 * whose secrets did not come across and to name the missing variables; with one
 * name out of N it named the wrong thing and passed the rest.
 */
export function parseComposeRequiredVars(stdout: string): string[] {
  const required = new Set<string>();
  for (const tok of cleanRows(stdout, 6000)) {
    const m = /^\$\{([A-Za-z_][A-Za-z0-9_]*)(:?[-?+])?/.exec(tok);
    if (!m || m[2]) continue; // `${VAR:-default}` supplies its own value
    required.add(m[1]);
  }
  return [...required];
}

