export type CertMismatchInput = {
  /** The certificate this server actually presents for `domain`, from SNI. */
  certNames: string[];
  domain: string;
  /** Did the OLD server answer this name over TLS? (its own vhost said `ssl`) */
  sourceServedHttps: boolean;
  /** Do we hold a certificate for this name here, or did we just issue one? */
  weHoldACert: boolean;
};

export type CertMismatchVerdict =
  /** Nothing wrong: the name is covered, or 443 is irrelevant to it. */
  | { kind: "ok" }
  /** We broke a site that used to be HTTPS. Counts as NOT serving. */
  | { kind: "regression"; reason: string }
  /** Pre-existing: it was plain HTTP before and still is. Serving, but say so. */
  | { kind: "preexisting"; note: string };

/**
 * Decide what a certificate mismatch on :443 MEANS for one hostname.
 *
 * Incident (2026-07-26 rehearsal): the check ran whenever anything was listening
 * on 443 and treated every mismatch as "NOT serving — every visitor gets a
 * full-page browser security warning". `blog.othertenant.example.net` was
 * HTTP-only on the source, served byte-identical content on the target, and was
 * reported dark. Running `openssl s_client -servername blog…` against the SOURCE
 * returned the same foreign certificate: the migration was penalised for
 * faithfully reproducing a pre-existing condition. On the ordinary HestiaCP /
 * cPanel shape — some vhosts with certificates, most without — that marks nearly
 * every site on the box as broken, and a gate that always cries wolf is how a
 * genuinely dark domain ships.
 *
 * The distinction is EVIDENCE, not a guess. `sourceServedHttps` comes from the
 * old server's own merged vhost config (`ssl` on its server block), so:
 *
 *   - it was HTTPS there and is broken here  → regression, a real failure;
 *   - it was plain HTTP there and is plain HTTP here → nothing was broken, but
 *     the summary still says https:// shows a warning and how to fix it.
 *
 * Note the second case is NOT "assume success": the site is only called serving
 * because a REAL request to it returned real content. The warning is still
 * reported, with the certbot command — it just is not counted as this
 * migration's failure.
 */
export function certMismatchVerdict(input: CertMismatchInput): CertMismatchVerdict {
  const { certNames, domain, sourceServedHttps, weHoldACert } = input;
  if (!certNames.length) return { kind: "ok" }; // nothing presented; nothing to judge
  if (certCoversName(certNames, domain)) return { kind: "ok" };
  const presented = certNames.slice(0, 3).join(", ");
  if (sourceServedHttps || weHoldACert) {
    return {
      kind: "regression",
      reason:
        `this server answers https://${domain}/ with a certificate issued for ${presented}, which does not cover ${domain} — ` +
        `the old server served this name over HTTPS, so every visitor now gets a full-page browser security warning before they reach the site`,
    };
  }
  return {
    kind: "preexisting",
    note:
      `no certificate covers ${domain} here (:443 presents one for ${presented}), exactly as on the old server — ` +
      `this name was plain HTTP there too, so nothing was broken by the move. Once DNS points here, issue one with: ` +
      `certbot --nginx -d ${domain}`,
  };
}

