/**
 * What to tell the customer about a service whose unit file we could NOT pull
 * from the source's `/etc/systemd/system`.
 *
 * Incident (2026-07-26 rehearsal): the rsync fails for every DISTRO-packaged
 * unit, because those live in `/lib/systemd/system`, not `/etc`. The code then
 * pushed one identical action item per unit — "unit not a simple
 * /etc/systemd/system file — re-enable manually" — for `containerd`, `docker`,
 * `exim4`, `mariadb`, `nginx`, `qemu-guest-agent` and `serial-getty@ttyS0`.
 * Seven of the run's twenty-two `needsAttention` entries were instructions to
 * hand-re-enable software the target had already installed and already had
 * RUNNING, in the same summary that said `nginx restarted`. It also contradicts
 * field note 27's rule about not re-enabling a web server off the source's list.
 *
 * Noise is not harmless here: the two entries that were real were buried in it.
 *
 * The verdict is driven ONLY by what was actually observed on the target, never
 * by a package-name allowlist — the point is to stop guessing, not to guess
 * differently.
 */
export function distroUnitVerdict(input: {
  svc: string;
  /** `systemctl list-unit-files <svc>.service` found it on the TARGET. */
  presentHere: boolean;
  /** `systemctl is-active <svc>` said active on the TARGET. */
  activeHere: boolean;
}): { status: MigrationStepResult["status"]; detail: string } {
  const { svc, presentHere, activeHere } = input;
  if (activeHere) {
    return {
      status: "running",
      detail: `this server provides ${svc} itself and it is already running — the old server's copy was a distribution package, not a custom unit, so there is nothing to move`,
    };
  }
  if (presentHere) {
    return {
      status: "copied",
      detail: `${svc} is installed on this server but is not running. It was a distribution package on the old server, so there is no custom unit to copy. If your setup needs it: systemctl enable --now ${svc}`,
    };
  }
  return {
    status: "copied",
    detail:
      `${svc} ran on the old server but its unit is not a plain /etc/systemd/system file, and this server does not have ${svc} at all — ` +
      `so it was NOT migrated and nothing here provides it. Install it and enable it: apt-get install -y ${svc} && systemctl enable --now ${svc}`,
  };
}

