cat >> /opt/nxeon/test/migration-gate.test.ts <<'EOF'

/* ------------------------------------------------------------------ *
 * 7. Row structure survives sanitisation
 *
 * The 2026-07-26 rehearsal — the first time this engine was ever run end to end
 * against a purpose-built messy source — found the same bug in six places at
 * once. `clean()` strips every control character INCLUDING \n and \t, and six
 * verification paths called it and then split the result on \n or looked for a
 * \t. Each one silently parsed a single glued row, and each one had surrounding
 * code that reported a conclusion on the strength of that empty parse.
 *
 * These are not six typos. They are one lesson (already written down in this
 * codebase, for `probeBody`, and applied nowhere else) that had to be re-learned
 * by running the thing. Every parser below is now a named function so it can be
 * given the exact bytes the real command produced.
 * ------------------------------------------------------------------ */

test("cleanRows keeps rows apart while still removing control characters", () => {
  // The distinguishing property: `clean` would return ONE element here.
  const rows = cleanRows("alpha\nbeta\tgamma\n\x00delta\x07\n\n  \n", 4096);
  assert.deepEqual(rows, ["alpha", "beta\tgamma", "delta"]);
  assert.ok(rows.length > 1, "the whole point: a multi-row output stays multi-row");
  assert.ok(rows[1].includes("\t"), "tabs survive — column parsers depend on them");
  assert.ok(!rows.some((r) => /[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/.test(r)), "other control characters are still stripped");
  assert.deepEqual(cleanRows("", 10), [], "empty output is no rows, not one empty row");
  assert.deepEqual(cleanRows(null, 10), []);
});

test("every TCP port is read from ss, not just the last one on the box", () => {
  // Incident: `clean(stdout).split("\n")` glued ss's output into one string and
  // the `$`-anchored /:(\d{1,5})$/ then matched ONLY the final port. `listening`
  // held one port at random. `appPorts` is filtered through this set and is the
  // fallback upstream for synthesising a vhost — so a container app that was up
  // and bound got no vhost, and the customer's domain served the stock distro
  // page. This is the exact `ss -lnt | awk '{print $4}'` output from the run.
  const ss = "Local Address:Port\n0.0.0.0:22\n0.0.0.0:80\n127.0.0.1:3105\n[::]:443\n127.0.0.1:3306\n";
  const ports = parseListeningPorts(ss);
  assert.equal(ports.size, 5, "five bound ports, not one");
  for (const p of [22, 80, 443, 3105, 3306]) assert.ok(ports.has(p), `port ${p} was found`);
  assert.ok(!ports.has(0));
  // The header row carries no port and must not become one.
  assert.deepEqual([...parseListeningPorts("Local Address:Port\n")], []);
  // Out-of-range never enters the set.
  assert.ok(!parseListeningPorts("0.0.0.0:99999\n").has(99999));
});

test("database accounts are read back per row, so a working account is never called missing", () => {
  // Incident: `mysql -N -B` is TAB-separated, one account per line. The old
  // parse was clean().split("\n").map(l => l.split(/\s+/).slice(0,2).join("@")),
  // and clean deletes BOTH separators — the whole table became the single key
  // "readonly%shopapplocalhost". `landed` was therefore always empty and the run
  // pushed, at status `failed`, "none of the 3 application database account(s)
  // could be recreated". Ground truth that day: all three existed with their
  // original password hashes and grants, and the apps could log in.
  const out = "root\tlocalhost\nmysql.sys\tlocalhost\nshopapp\tlocalhost\nreadonly\t%\nblog\t10.20.0.%\n";
  const present = parseMysqlUserList(out);
  assert.ok(present.has("shopapp@localhost"), "the account the customer was told to recreate by hand");
  assert.ok(present.has("readonly@%"));
  assert.ok(present.has("blog@10.20.0.%"));
  assert.equal(present.size, 5);
  assert.ok(!present.has("readonly%shopapplocalhost"), "the glued fingerprint of the bug is gone");

  // The consequence the fix is really about: matching the inventory's accounts.
  const accounts = [
    { user: "shopapp", host: "localhost" },
    { user: "readonly", host: "%" },
    { user: "blog", host: "10.20.0.%" },
  ];
  const landed = accounts.filter((a) => present.has(`${a.user}@${a.host}`));
  assert.equal(landed.length, 3, "3 of 3 landed — the run reported 0 of 3");
});

test("an empty mysql.user read is 'not verified', never 'none could be recreated'", () => {
  // mysql.user always contains root and the distro maintenance account, so an
  // empty result means the QUERY failed, not that the accounts are absent. The
  // house rule: a surface must never report an outcome it did not verify, and
  // "your apps will get access-denied" is a very different claim from "we could
  // not check". The caller keys this off present.size.
  assert.equal(parseMysqlUserList("").size, 0);
  assert.equal(parseMysqlUserList("   \n \n").size, 0);
  assert.ok(parseMysqlUserList("root\tlocalhost\n").size > 0, "a live engine is never empty");
});

test("the stale-reference sweep parses its tab-delimited hits", () => {
  // Incident: the loop read clean(stdout).split("\n") and its FIRST statement was
  // `if (raw.indexOf("\t") < 0) continue`. clean strips tabs unconditionally, so
  // the guard was taken on every line, on every run this code has ever had — a
  // 100% failure, not an order-dependent one. This is the detection for field
  // note 11 ("a frontend calling the old server's API is a silent failure").
  const out =
    "HIT\t/var/www/app/.env:12:10.20.0.150\n" +
    "HIT\t/var/www/app/dist/main.js:1:10.20.0.150\n" +
    "HIT\t/var/www/app/.env:12:10.20.0.150\n" + // duplicate file|value
    "CERTREF\t/etc/nginx/sites-enabled/shop:34:/etc/letsencrypt/live/shop.example.com\n" +
    "SWEEP_OK\t1\n";
  const r = parseStaleSweep(out);
  assert.equal(r.hits.length, 2, "two distinct hits; the duplicate collapses");
  assert.equal(r.hits[0].file, "/var/www/app/.env");
  assert.equal(r.hits[0].line, 12);
  assert.equal(r.hits[0].value, "10.20.0.150");
  assert.equal(r.certRefs.get("shop.example.com"), "/etc/nginx/sites-enabled/shop");
  assert.ok(r.ok, "the completion marker was seen");
});

test("a sweep that did not finish is not a clean bill of health", () => {
  // The second half of the same incident, and the one that matters most. The run
  // logged "Scanning the copied files for anything still pointing at the old
  // server" and then pushed `Old-server references` into verifiedRunning at
  // status `running` — "nothing in the copied files still points at the old
  // server" — produced by parsing zero lines. SWEEP_OK was already being printed
  // by the script and had never been read. No hits and no marker must NOT read
  // the same as no hits and a marker.
  const killed = parseStaleSweep("HIT\t/var/www/app/.env:12:10.20.0.150\n"); // timeout: no marker
  assert.equal(killed.ok, false, "without SWEEP_OK nothing was proven");
  assert.equal(parseStaleSweep("").ok, false, "no output at all is not success");
  assert.equal(parseStaleSweep("SWEEP_OK\t1\n").ok, true, "a genuinely clean tree still reports clean");
  assert.equal(parseStaleSweep("SWEEP_OK\t1\n").hits.length, 0);
});

test("every compose variable without a default is required, not just the first", () => {
  // Incident: `grep -o '${...}'` emits one token per line; glued they became
  // "${DB_PASSWORD}${REDIS_URL}${API_KEY}" and the ^-anchored regex returned only
  // DB_PASSWORD. Field note 12 exists to REFUSE to start a stack whose secrets
  // did not come across, naming the missing variables — with one name out of
  // three it named the wrong thing and passed the rest.
  const grep = "${DB_PASSWORD}\n${REDIS_URL}\n${API_KEY}\n${PORT:-8080}\n${TAG-latest}\n${DB_PASSWORD}\n";
  const vars = parseComposeRequiredVars(grep);
  assert.deepEqual(vars.sort(), ["API_KEY", "DB_PASSWORD", "REDIS_URL"]);
  assert.ok(!vars.includes("PORT"), "${VAR:-default} supplies its own value");
  assert.ok(!vars.includes("TAG"), "${VAR-default} too");
  assert.equal(new Set(vars).size, vars.length, "duplicates collapse");
});

/* ------------------------------------------------------------------ *
 * 8. A pre-existing plain-HTTP site is not a migration failure
 *
 * The cert check exists because studionexis.com was served
 * nexis.revsports.ca's certificate and every visitor hit a full-page browser
 * warning. But it ran on ANY mismatch whenever something was listening on 443,
 * so in the rehearsal blog.othertenant.example.net — HTTP-only on the source,
 * serving byte-identical content on the target — was declared dark. Running
 * `openssl s_client -servername blog…` against the SOURCE returned the same
 * foreign certificate: the migration was marked down for faithfully reproducing
 * a pre-existing condition.
 *
 * On the ordinary HestiaCP/cPanel shape (a few vhosts with certificates, most
 * without) that marks nearly every site on the box broken — and a gate that
 * always cries wolf is how a genuinely dark domain ships.
 * ------------------------------------------------------------------ */

test("a site the OLD server served over HTTPS, broken here, is still a real failure", () => {
  // The studionexis.com incident itself. This must not regress.
  const v = certMismatchVerdict({
    certNames: ["nexis.revsports.ca"],
    domain: "studionexis.com",
    sourceServedHttps: true,
    weHoldACert: false,
  });
  assert.equal(v.kind, "regression");
  assert.match(v.kind === "regression" ? v.reason : "", /nexis\.revsports\.ca/);
  assert.match(v.kind === "regression" ? v.reason : "", /security warning/);
});

test("a site that was plain HTTP before and still is was not broken by the move", () => {
  const v = certMismatchVerdict({
    certNames: ["shop.rehearsal-src.example.com"],
    domain: "blog.othertenant.example.net",
    sourceServedHttps: false,
    weHoldACert: false,
  });
  assert.equal(v.kind, "preexisting", "serving, exactly as it did on the old server");
  // Not-our-failure must still not mean not-mentioned: the customer hears about
  // the warning and gets the command that clears it.
  const note = v.kind === "preexisting" ? v.note : "";
  assert.match(note, /as on the old server/);
  assert.match(note, /certbot --nginx -d blog\.othertenant\.example\.net/);
});

test("holding a certificate ourselves makes a mismatch our failure again", () => {
  // We issued (or migrated) a certificate for this name, so :443 answering with
  // someone else's is our vhost/cert wiring being wrong — regardless of what the
  // source did.
  const v = certMismatchVerdict({
    certNames: ["other.example.com"],
    domain: "shop.example.com",
    sourceServedHttps: false,
    weHoldACert: true,
  });
  assert.equal(v.kind, "regression");
});

test("a covering certificate, or none presented at all, is never a mismatch", () => {
  assert.equal(
    certMismatchVerdict({ certNames: ["shop.example.com"], domain: "shop.example.com", sourceServedHttps: true, weHoldACert: true }).kind,
    "ok",
  );
  assert.equal(
    certMismatchVerdict({ certNames: ["*.example.com"], domain: "shop.example.com", sourceServedHttps: true, weHoldACert: true }).kind,
    "ok",
    "wildcard coverage is still coverage",
  );
  assert.equal(
    certMismatchVerdict({ certNames: [], domain: "shop.example.com", sourceServedHttps: true, weHoldACert: false }).kind,
    "ok",
    "nothing presented means nothing to judge — we do not invent a verdict",
  );
});

/* ------------------------------------------------------------------ *
 * 9. Do not hand the customer action items the machine already did
 *
 * Distro units live in /lib/systemd/system, so pulling
 * /etc/systemd/system/<svc>.service off the source ALWAYS fails for them. The
 * engine then pushed one identical "re-enable manually" line per unit. In the
 * rehearsal that was seven of twenty-two needsAttention entries — containerd,
 * docker, exim4, mariadb, nginx, qemu-guest-agent, serial-getty@ttyS0 — telling
 * the customer to hand-re-enable software the target had already installed and
 * was already RUNNING, in the same summary that said `nginx restarted`. The two
 * entries that were real were buried in it.
 * ------------------------------------------------------------------ */

test("a service this server already runs is not an action item", () => {
  const v = distroUnitVerdict({ svc: "nginx", presentHere: true, activeHere: true });
  assert.equal(v.status, "running", "verified up on the target — not 'copied, needs attention'");
  assert.match(v.detail, /already running/);
  assert.ok(!/re-enable manually/.test(v.detail));
});

test("installed but stopped is reported honestly, with the command", () => {
  const v = distroUnitVerdict({ svc: "exim4", presentHere: true, activeHere: false });
  assert.equal(v.status, "copied");
  assert.match(v.detail, /not running/);
  assert.match(v.detail, /systemctl enable --now exim4/, "every blocker carries a fix the customer can run");
});

test("a service that is genuinely absent here says so plainly, and is not softened", () => {
  // The case the old blanket message was actually right about — it must survive,
  // and it must say the thing that matters: nothing here provides this.
  const v = distroUnitVerdict({ svc: "redis-server", presentHere: false, activeHere: false });
  assert.equal(v.status, "copied");
  assert.match(v.detail, /was NOT migrated/);
  assert.match(v.detail, /does not have redis-server at all/);
  assert.match(v.detail, /apt-get install -y redis-server/);
});
